import json, sys, pathlib

here = pathlib.Path(__file__).parent
tour = json.load(open(here / 'tour.json', encoding='utf-8'))
L = ['#pragma once', '',
     '// Generated by tools/subareas/make_tour.py: photo tour of every sub area, inside (entrance label of the sub area)',
     '// and outside (exit label of the sub area in its parent stage, so the game puts Mario at the pipe / door)', '',
     'namespace btt {', '',
     'struct PhotoTourShot {', '    const char* shot;', '    const char* stage;', '    const char* label;', '};', '',
     'inline constexpr PhotoTourShot sPhotoTourShots[] = {']
for t in tour:
    L.append(f'    {{ "{t["shot"]}", "{t["stage"]}", "{t["label"]}" }},')
L += ['};', '', 'inline constexpr int cPhotoTourShotNum = sizeof(sPhotoTourShots) / sizeof(sPhotoTourShots[0]);', '',
      '} // namespace btt', '']
pathlib.Path(sys.argv[1]).write_bytes('\n'.join(L).encode())
print(len(tour))
